insert into public.case_bank
  (title, story, side_a_who, side_a, side_b_who, side_b, clues, answer, explanation, category, source, review_flags, status)
values
  ('The dead tree and the crushed car', 'A storm knocked Graham''s oak onto his neighbour Priya''s new car: $7,900 of damage. Eight months earlier, Priya had warned him in writing that the tree was rotten and leaning. He did nothing.', 'Priya', 'Priya', 'Graham', 'Graham', '{}'::text[], 'A', 'A healthy tree falling in a storm is nobody''s fault. A rotten one the owner was warned about in writing usually is.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The nursing course: loan or gift?', 'Daniel paid $6,500 for his girlfriend Amara''s nursing course. That week she texted: “I''ll pay you back every penny once I''m qualified.” They''ve broken up, she''s qualified, and he wants the money.', 'Daniel', 'Daniel', 'Amara', 'Amara', '{}'::text[], 'A', 'A loan doesn''t need a contract. Her own text promising to repay is strong evidence it was a loan.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('Who keeps the engagement ring?', 'Marcus gave Jade a $5,000 engagement ring. Three months before the wedding, she found out he''d cheated and called it off. Now he wants the ring back.', 'Marcus', 'Marcus', 'Jade', 'Jade', '{}'::text[], 'A', 'Many courts treat an engagement ring as a gift on condition of marriage: no wedding, it goes back, whoever caused the breakup.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The friend who crashed my car', 'Kemi lent her car to her friend Zara, who rear-ended a van while checking her phone. Kemi paid a $750 insurance excess, and her premium jumped $420 because of the claim.', 'Kemi', 'Kemi', 'Zara', 'Zara', '{}'::text[], 'A', 'The driver who causes a crash usually owes the losses it caused, and the insurer blamed the claim for the higher premium.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The mouldy flat and the broken lease', 'Sophie reported black mould to her landlord in writing four times. He told her to open a window. Her toddler started wheezing, so she moved out six months early. An inspector later found a leaking gutter behind the wall.', 'Sophie', 'Sophie', 'The landlord', 'The landlord', '{}'::text[], 'A', 'Landlords must keep a home fit to live in. Ignoring four written reports of a leak usually frees the tenant.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The $300 quote and the $1,400 bill', 'A garage quoted Ibrahim $300 for brake pads. Without asking him, they also did $1,100 of other work, though the form he signed says extra work needs his approval. They won''t release the car until he pays it all.', 'Ibrahim', 'Ibrahim', 'The garage', 'The garage', '{}'::text[], 'A', 'A quote is the limit of what the customer agreed to. Extra work needs approval, and the garage''s own form says so.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The wedding photos they won''t pay for', 'Chidi and Ruth hired a photographer known for dark, moody photos, and told her they loved that style. Now they hate the result and won''t pay the last $1,500 unless she re-edits everything brighter.', 'The couple', 'The couple', 'The photographer', 'The photographer', '{}'::text[], 'B', 'Creative work that''s professional and matches what was agreed is a done deal. Disliking it isn''t a breach.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The dress for a wedding that never happened', 'Funmi paid $4,000 for a made-to-measure wedding dress. When her fiancé called off the wedding, she cancelled, but the dress was already cut to her size. The terms she initialled say no refunds once cutting begins.', 'Funmi', 'Funmi', 'The dress shop', 'The dress shop', '{}'::text[], 'B', 'Made-to-measure goods are a classic no-refund case, especially with clear terms she signed.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('Sold as seen, dead in a week', 'Kwame bought a used SUV privately for $9,500, “sold as seen.” He turned down an inspection. A week and 900 miles later, the engine died.', 'Kwame', 'Kwame', 'The seller', 'The seller', '{}'::text[], 'B', 'In a private sale, the buyer takes the risk of hidden faults unless the seller lied about something they knew.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The friend who dropped out of the villa trip', 'Six friends booked a non-refundable villa, $700 each. The group chat rule was: drop out, find a replacement or lose your share. Ify agreed with 👍, then dropped out for a new job and wants her $700 back.', 'Ify', 'Ify', 'The group', 'The group', '{}'::text[], 'B', 'Ify agreed in writing to the rule. A good reason for leaving doesn''t change the deal.', 'small claims', 'bank', ARRAY['Check the answer: it reflects how small-claims courts commonly rule, and the rules differ by country.']::text[], 'draft'),
  ('The $1,200 bachelorette', 'Ada''s bachelorette is a $1,200 weekend in Dubai. Bisi, her maid of honour, can''t afford it and offered to host a party at home. Ada gave the role to her cousin instead.', 'Bisi', 'Bisi', 'Ada', 'Ada', '{}'::text[], 'jury', null, 'weddings', 'bank', '{}'::text[], 'draft'),
  ('The boyfriend who basically lives here', 'Rachel''s boyfriend sleeps over six nights a week, showers every morning and works from the living room. Her two flatmates want him to pay $150 a month.', 'The flatmates', 'The flatmates', 'Rachel', 'Rachel', '{}'::text[], 'jury', null, 'roommates', 'bank', '{}'::text[], 'draft'),
  ('She took my baby''s name', 'Years ago, Nkiru told the family she''d name her future daughter after their late grandmother. Her sister-in-law just had a baby girl and used the name.', 'Nkiru', 'Nkiru', 'The sister-in-law', 'The sister-in-law', '{}'::text[], 'jury', null, 'family', 'bank', '{}'::text[], 'draft'),
  ('Six years of caregiving, an equal split', 'Esther quit her job to care for her sick mother for six years. Her brothers sent money from abroad. The will splits the house three ways, and Esther wants more.', 'Esther', 'Esther', 'Her brothers', 'Her brothers', '{}'::text[], 'jury', null, 'family', 'bank', '{}'::text[], 'draft'),
  ('The recline on a 9-hour flight', 'Femi reclined all the way right after dinner on an overnight flight. The 6''4" man behind him, working on a laptop, asked him to come up halfway. Femi said no.', 'Femi', 'Femi', 'The man behind', 'The man behind', '{}'::text[], 'jury', null, 'travel', 'bank', '{}'::text[], 'draft'),
  ('No kids at the wedding, not even a newborn', 'Tosin''s wedding is adults only. Her friend Halima has a 3-month-old who won''t take a bottle and asked to bring her. Tosin said no exceptions.', 'Halima', 'Halima', 'Tosin', 'Tosin', '{}'::text[], 'jury', null, 'weddings', 'bank', '{}'::text[], 'draft'),
  ('My idea, your $2 million business', 'At dinner five years ago, Seun described an app idea in detail. Her friend Chioma later built it and sold the business for $2 million. Seun wants 10%.', 'Seun', 'Seun', 'Chioma', 'Chioma', '{}'::text[], 'jury', null, 'friends', 'bank', '{}'::text[], 'draft'),
  ('The secret $18,000', 'Musa found out his wife Zainab has secretly saved $18,000 over six years in an account in her own name. She calls it her “just in case” money.', 'Musa', 'Musa', 'Zainab', 'Zainab', '{}'::text[], 'jury', null, 'relationships', 'bank', '{}'::text[], 'draft'),
  ('Mum and Dad want the fees back', 'Obi''s parents paid $40,000 for his degree. Now he''s moved abroad, and they want him to repay $500 a month. Repayment was never mentioned before.', 'Obi', 'Obi', 'His parents', 'His parents', '{}'::text[], 'jury', null, 'family', 'bank', '{}'::text[], 'draft'),
  ('The whole class except one', 'Nkechi invited all 24 kids in her daughter''s class to her party except Leo, who bit her daughter two months ago. Leo found out at school and cried.', 'Leo''s mother', 'Leo''s mother', 'Nkechi', 'Nkechi', '{}'::text[], 'jury', null, 'parenting', 'bank', '{}'::text[], 'draft'),
  ('The neighbour''s Wi-Fi', 'Mrs. Bello gave her new neighbour her Wi-Fi password “until you get set up.” That was 14 months ago. Now her bill has gone up, and she wants $420.', 'Mrs. Bello', 'Mrs. Bello', 'The neighbour', 'The neighbour', '{}'::text[], 'jury', null, 'neighbours', 'bank', '{}'::text[], 'draft'),
  ('The $85 no-show', 'Dami confirmed twice for Yemi''s $85-a-head birthday dinner, then didn''t show or answer her phone. The restaurant charged Yemi for the empty seat.', 'Yemi', 'Yemi', 'Dami', 'Dami', '{}'::text[], 'jury', null, 'friends', 'bank', '{}'::text[], 'draft'),
  ('The lottery syndicate and the missing $5', 'Eight coworkers have played the lottery together for three years. Seyi was off sick one week and didn''t pay his $5. That ticket won $640,000.', 'Seyi', 'Seyi', 'The other seven', 'The other seven', '{}'::text[], 'jury', null, 'work', 'bank', '{}'::text[], 'draft'),
  ('The window seat I paid extra for', 'Grace paid extra for a window seat. A mother asked her to swap for a middle seat at the back so she could sit with her 4-year-old. Grace said no.', 'Grace', 'Grace', 'The mother', 'The mother', '{}'::text[], 'jury', null, 'travel', 'bank', '{}'::text[], 'draft'),
  ('The best man speech that went too far', 'In his speech, best man Tayo told 200 guests the groom had called him the night before, unsure he loved the bride. The groom had OK''d a draft, but not that line.', 'The groom', 'The groom', 'Tayo', 'Tayo', '{}'::text[], 'jury', null, 'weddings', 'bank', '{}'::text[], 'draft'),
  ('Who gets the dog?', 'Ade and Lara adopted a dog together. Ade paid for everything and the papers are in his name. Lara did the walks and feeding. When they split, she took the dog.', 'Ade', 'Ade', 'Lara', 'Lara', '{}'::text[], 'jury', null, 'relationships', 'bank', '{}'::text[], 'draft'),
  ('Quit the day after the company trip', 'Ola''s company sent her on a $4,000 trip as a top performer. She signed with a competitor during the trip and quit the day after she got back.', 'Her manager', 'Her manager', 'Ola', 'Ola', '{}'::text[], 'jury', null, 'work', 'bank', '{}'::text[], 'draft'),
  ('Same rent, bigger room', 'Tolu found the flat and did all the paperwork. Now she wants the big room with its own bathroom, at the same rent as the two small rooms.', 'Tolu', 'Tolu', 'The other two', 'The other two', '{}'::text[], 'jury', null, 'roommates', 'bank', '{}'::text[], 'draft'),
  ('I had a salad, you had the lobster', 'Ngozi ordered a $14 salad at a group birthday dinner. Others had lobster and wine. They want to split the $720 bill evenly: $103 each.', 'Ngozi', 'Ngozi', 'The table', 'The table', '{}'::text[], 'jury', null, 'money', 'bank', '{}'::text[], 'draft'),
  ('Game night with the ex', 'Ben has played board games every Thursday for six years with friends, including his ex from ten years ago. His girlfriend wants him to stop going.', 'His girlfriend', 'His girlfriend', 'Ben', 'Ben', '{}'::text[], 'jury', null, 'relationships', 'bank', '{}'::text[], 'draft'),
  ('A stranger at your door at 2am', 'It''s 2am. A stranger knocks, says their car broke down and their phone is dead, and asks to come in and use yours.', 'Let them in', 'Let them in', 'Keep the door shut', 'Keep the door shut', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('The bank sent you $2,000 by mistake', 'You check your account and there''s an extra $2,000 from a name you don''t know. Nobody has asked for it back yet.', 'Report it today', 'Report it today', 'Wait and see', 'Wait and see', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('Your friend''s partner is on a dating app', 'You match with your best friend''s boyfriend on a dating app. His profile was updated yesterday.', 'Tell your friend', 'Tell your friend', 'Stay out of it', 'Stay out of it', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('The wedding dress is a mistake', 'A week before her wedding, your best friend tries on her dress and asks for your honest opinion. You think it''s awful.', 'Tell the truth', 'Tell the truth', 'Say she looks stunning', 'Say she looks stunning', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('The coworker about to sign a lease', 'You overhear that a coworker will be let go on Friday. Today they tell you they''re signing a pricey new lease tomorrow.', 'Warn them', 'Warn them', 'Keep quiet', 'Keep quiet', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('The free $60 dinner', 'The restaurant forgot to put your $60 main on the bill. The waiter is busy and you''re about to leave.', 'Tell the waiter', 'Tell the waiter', 'Enjoy the free meal', 'Enjoy the free meal', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('Your sibling wants another loan', 'Your brother asks to borrow $1,000. He still owes you $500 from last year, but he says this time it''s an emergency.', 'Lend it', 'Lend it', 'Not until he pays', 'Not until he pays', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('The ''I miss you'' text at midnight', 'Your ex, who you haven''t heard from in a year, texts at midnight: “I miss you.”', 'Reply', 'Reply', 'Leave it on read', 'Leave it on read', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('Your friend''s terrible restaurant dream', 'Your friend is quitting their job to open a restaurant. Their cooking is honestly bad. They ask what you think.', 'Be honest', 'Be honest', 'Back the dream', 'Back the dream', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft'),
  ('Found: a wallet with $500 cash', 'You find a wallet on the street with $500 and an ID. The address on the ID is two hours away.', 'Post it back with the cash', 'Post it back with the cash', 'Hand it in to the police', 'Hand it in to the police', '{}'::text[], 'jury', null, 'what would you do', 'bank', '{}'::text[], 'draft');
